#!/usr/bin/env python3
"""Deterministically materialize frozen Phase 0 v8 from the byte-verified v7 base."""
from pathlib import Path
import json, shutil, sys

src=Path(sys.argv[1])
dst=Path(sys.argv[2])
dst.mkdir(parents=True,exist_ok=True)

for fn in ("nis2_country_registry.json","cpv_definitions.json"):
    shutil.copyfile(src/fn,dst/fn)

P8 = json.loads(r"""{"specification_version": "PHASE0_LOCKED_V8", "frozen": true, "freeze_date": "2026-08-31", "locked_input_hashes": {"nis2_country_registry_sha256": "a719f44fea61abac1963947d0df5b93a0a1de1bcd5f83ef1c7436948a89959fc", "cpv_definitions_sha256": "ad2c53421c20871db3b178c920cdfa4fe9f933578f5f36d9b0be0b9df46f89db"}, "global_parameters": {"min_effect_pp": 10.0, "commercial_lead_days": 90, "leave_one_country_out_min_share_passing": 0.8, "alternative_baseline_tolerance_pp": 5.0}, "panel_policy": {"buyer_scope": "ALL_TED_BUYERS_CONSERVATIVE", "buyer_scope_note": "No post-outcome sector filtering is allowed in the primary gate. This is deliberately conservative and avoids unstable historical MAIN_ACTIVITY mappings. Sector-filtered analysis may be exploratory only and cannot rescue a failed primary gate.", "distinct_notice_counting": true, "zero_fill_country_month_arm": true, "notice_universe": "COMPETITION_CONTRACT_NOTICES", "time_field": "DISPATCH_DATE", "historical_notice_types": "TED_CSV_CONTRACT_NOTICES", "modern_notice_types": ["cn-standard", "cn-social", "cn-desg"], "source_population_consistency_required": true, "transport": "TED_SEARCH_API_SERVER_SIDE_FIELD_PROJECTION_ONLY", "allowed_persisted_fields": ["notice_id", "dispatch_date", "buyer_country", "cpv_code"], "raw_bulk_downloads_forbidden": true, "personal_data_processing_forbidden": true}, "benchmarks": {"NIS1": {"design": "matched_cpv_prepost", "catalyst_known_date": "2016-07-06", "pre_window_start": "2016-09-01", "pre_window_end": "2018-04-01", "effect_window_start": "2018-05-01", "effect_window_end": "2020-04-01", "treated_definition_id": "NIS_TREATED_V1", "control_definition_id": "IT_NEUTRAL_CONTROL_V1", "balanced_country_min_share": 0.8, "alternative_baseline_start": "2017-05-01", "alternative_baseline_end": "2018-04-01"}, "GDPR": {"design": "matched_cpv_prepost", "catalyst_known_date": "2016-04-27", "pre_window_start": "2016-09-01", "pre_window_end": "2018-04-01", "effect_window_start": "2018-05-01", "effect_window_end": "2020-04-01", "treated_definition_id": "GDPR_TREATED_V1", "control_definition_id": "IT_NEUTRAL_CONTROL_V1", "balanced_country_min_share": 0.8, "alternative_baseline_start": "2017-05-01", "alternative_baseline_end": "2018-04-01"}, "NIS2": {"design": "staggered_ddd_fixed_precatalyst_baseline_with_anticipation_guard", "analysis_cutoff_date": "2026-08-31", "catalyst_known_date": "2022-12-14", "treated_definition_id": "NIS_TREATED_V1", "control_definition_id": "IT_NEUTRAL_CONTROL_V1", "normalization_baseline_start": "2021-01-01", "normalization_baseline_end": "2022-11-01", "alternative_baseline_start": "2022-01-01", "alternative_baseline_end": "2022-11-01", "min_baseline_months": 10, "effect_event_month_start": 0, "effect_event_month_end": 11, "lead_sustain_months": 3, "comparative_pretrend_event_month_start": -12, "comparative_pretrend_event_month_end": -3, "comparative_pretrend_abs_max_pp": 7.5, "direct_pretrend_event_month_start": -12, "direct_pretrend_event_month_end": -3, "direct_pretrend_slope_abs_max_pp_per_month": 0.5, "direct_pretrend_country_pass_share": 0.8, "late_anticipation_event_month_start": -2, "late_anticipation_event_month_end": -1, "late_anticipation_signal_threshold_pp": 10.0, "late_anticipation_policy": "DIAGNOSTIC_ONLY: a T-2/T-1 signal neither passes nor fails the NIS2 benchmark and cannot rescue a failed post-treatment Phase 0 gate.", "primary_anticipation_buffer_months": 12, "robustness_anticipation_buffer_months": 18, "min_not_yet_treated_controls_per_att": 2, "min_att_observations": 12, "min_treated_countries": 4}}, "pre_outcome_correction_from_v6": {"reason": "TED Search API scope=ALL is a rolling ten-year search population, so May-Aug 2016 cannot be populated through the same all-notice Search API used for later years. No real outcome counts were opened before this correction.", "primary_notice_universe": "COMPETITION_CONTRACT_NOTICES", "time_field": "DISPATCH_DATE", "historical_transport_2016_2023": "OFFICIAL_TED_CSV_CONTRACT_NOTICES", "modern_transport_2024_2026": "TED_SEARCH_API_NOTICE_TYPES_CN_STANDARD_CN_SOCIAL_CN_DESG", "why_substantively_better": "Competition/Contract Notices represent calls for competition, i.e. the commercially actionable procurement opportunity, rather than awards/results/corrections."}, "pre_outcome_privacy_correction_from_v7": {"reason": "The official historical annual Contract Notice ZIPs can contain fields outside the four-field non-personal schema. Downloading the raw ZIP would itself violate the absolute no-personal-data processing requirement, even if those columns were projected out immediately after parsing. No v7 outcome result is valid or admissible.", "correction": "Use TED Search API only, with server-side field projection, over the maximum common privacy-safe historical window available at the 2026-08-31 analysis cutoff.", "earliest_common_date": "2016-09-01", "old_pre_window_start": "2016-05-01", "new_pre_window_start": "2016-09-01", "months_removed": ["2016-05", "2016-06", "2016-07", "2016-08"], "outcomes_seen_before_correction": false, "invalidated_runs": ["PHASE0_LOCKED_V7 real-data attempts"]}}""")
(dst/"phase0_preregistration.json").write_text(
    json.dumps(P8,indent=2,ensure_ascii=False),encoding="utf-8"
)

builder=(src/"build_phase0_panel_v7.py").read_text(encoding="utf-8")
builder=builder.replace("PHASE0_PANEL_V7_COMPETITION_DISPATCH",
                        "PHASE0_PANEL_V8_COMPETITION_DISPATCH")
builder=builder.replace("Phase 0 v7","Phase 0 v8")
(dst/"build_phase0_panel_v8.py").write_text(builder,encoding="utf-8")

engine=(src/"regulatory_demand_phase0_v7.py").read_text(encoding="utf-8")
engine=engine.replace("PHASE0_LOCKED_V7","PHASE0_LOCKED_V8")
engine=engine.replace("PHASE0_PANEL_V7_COMPETITION_DISPATCH",
                      "PHASE0_PANEL_V8_COMPETITION_DISPATCH")
engine=engine.replace("Phase 0 hard falsification gate v7",
                      "Phase 0 hard falsification gate v8")
(dst/"regulatory_demand_phase0_v8.py").write_text(engine,encoding="utf-8")
